public boolean validateRebateTable()
{
    TAMRebateTable  rebateTableLoc,rebateTableCount;
    TAMRebateDeal   rebateDeal;
    boolean rateSet=false,value=false;


    boolean ret;

    select firstonly rebateDeal
        where rebateDeal.RecId == this.RebateDeal;

    if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        select count(RecId) from rebateTableLoc
            where rebateTableLoc.RebateDeal == this.RebateDeal;

        if (rebateTableLoc.RecId > 2)
        {
            throw error("@MET:METVolumetricValidation");
        }

        select firstonly METTierLineType, RecId from rebateTableLoc
            where rebateTableLoc.RebateDeal == this.RebateDeal
            && rebateTableLoc.RecId != this.RecId;

        if (rebateTableLoc.RecId && this.RecId != rebateTableLoc.RecId && rebateTableLoc.METTierLineType == this.METTierLineType)
        {
            throw error("Volumetric rebate cannot have similar tier line type");
        }

        TAMRebateTable tamRebateTable;

        select firstonly tamRebateTable
            where tamRebateTable.RebateId != this.RebateId;

        if (tamRebateTable.RecId && tamRebateTable.pricingAttributeDetailsHeader() != this.pricingAttributeDetailsHeader())
        {
            warning(strFmt("Price attribuite details of the two rebates lines are not equal."));
        }

    }
    return ret;
}

/// <summary>
/// Before update the record validates the rebates should not have same line types and more than two records.
/// </summary>
public void update()
{
    TAMRebateDeal rebateDeal;

    select firstonly rebateDeal
        where rebateDeal.RecId == this.RebateDeal;

    if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        this.validateRebateTable();
    }

    next update();

    //if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    //{
    //    this.UpdateGUPPricingRuleCondition();
    //}
}

private void UpdateGUPPricingRuleCondition()
{
    GUPPricingRuleCondition gupPricingRuleCondition;
    GUPPricingRule gupPricingRule;
    TAMRebateTable tamRebateTable;

    Map conditionValueMap = new Map(Types::Int64, Types::String);

    while select ConditionAttribute, ConditionValue from gupPricingRuleCondition
        exists join gupPricingRule
            where gupPricingRule.RecId == gupPricingRuleCondition.RuleId
        exists join tamRebateTable
            where tamRebateTable.PricingRuleHeader == gupPricingRule.RecId
            && tamRebateTable.RebateId == this.RebateId
    {
        conditionValueMap.insert(gupPricingRuleCondition.ConditionAttribute, gupPricingRuleCondition.ConditionValue);
    }

    if (conditionValueMap.elements())
    {
        ttsBegin;
        select firstonly forupdate gupPricingRuleCondition
        exists join gupPricingRule
            where gupPricingRuleCondition.RuleId == gupPricingRule.RecId
        exists join tamRebateTable
            where tamRebateTable.PricingRuleHeader == gupPricingRule.RecId
            && tamRebateTable.RebateDeal == this.RebateDeal
            && tamRebateTable.RebateId != this.RebateId;

        if (gupPricingRuleCondition.RecId)
        {
            gupPricingRuleCondition.ConditionValue = strFmt("%1",conditionValueMap.lookup(gupPricingRuleCondition.ConditionAttribute));
            gupPricingRuleCondition.doUpdate();
        }
        ttsCommit;
    }
}
